<!--vbase-->
<template>
  <q-dialog
    v-model="show_popup"
    full-width
    @show="BeforePopupShow"
    @keydown.esc="cleanupOnhide"
    @hide="cleanupOnhide"
  >
    <!-- Inline width is intentional: Quasar's q-dialog caps the minimized inner
         at 560px, so the legacy .max-popup-size (width:90%) only resolved to ~90%
         of 560px. An inline style outranks that cap and guarantees a wide popup
         regardless of full-width quirks, so the log table shows all columns. -->
    <q-card class="max-popup-size" style="width: 92vw; max-width: 1400px;">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold text-white">{{ $t('import_log') }}</span>
        </q-toolbar-title>
        <q-btn
          flat
          round
          dense
          icon="close"
          color="white"
          @click="cleanupOnhide"
        />
      </q-toolbar>

      <q-card-section>
        <div class="q-pt-md">
          <q-input
            outlined
            dense
            v-model="filter"
            placeholder="Filter by Subject or Sender"
            @update:model-value="applyFilter"
            debounce="300"
            class="q-mb-sm width-25-percent"
          />
          <DocBitsTable
            :rows="rows"
            :columns="v2Columns"
            :column-order="v2ColumnOrder"
            row-key="id"
            table-id="import_log_table"
            :features="v2TableFeatures"
            :pagination="v2PaginationState"
            :loading="loading"
            table-height="65vh"
            no-data-label="no_data_found"
            @update:sorting="handleV2Sort"
            @update:pagination="handleV2Pagination"
            @column-reorder="handleV2ColumnReorder"
          >
            <template #body-cell-success="{ row }">
              <q-icon
                :name="getStatusIcon(row, 'email_import')[0]"
                :color="getStatusIcon(row, 'email_import')[1]"
                size="20px"
              />
            </template>
            <template #body-cell-message="{ row }">
              <span class="text-wrap-wrap">{{ row.message }}</span>
            </template>
            <template #body-cell-sender="{ row }">
              <div class="sender-cell">
                <span class="sender-name">{{ row.sender_display.name }}</span>
                <span
                  v-if="row.sender_display.email"
                  class="sender-email"
                >{{ row.sender_display.email }}</span>
              </div>
            </template>
          </DocBitsTable>
        </div>
      </q-card-section>

      <q-inner-loading :showing="loading" class="z-index-1">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">

import { LocalStorage } from 'quasar';
import { defineComponent } from 'vue';
import dateUtils from 'src/utils/date';
import { CONSTANTS } from 'src/constants';
import { importApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin';
import { getStatusIcon } from 'src/utils/general';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { DocBitsTable } from 'src/components/Table';
import type { UnifiedTableColumn, SortEventPayload, PaginationChangePayload } from 'src/components/Table';


export default defineComponent({
  mixins: [helperMixin, dateUtils],
  components: { DocBitsTable },
  props: {
    connection_id: { type: Number, required: false },
    show_import_logs: { type: Boolean, required: false },
  },
  data() {
    const default_order_by = { field_name: 'date', direction: 'desc' as 'asc' | 'desc' };
    return {
      default_order_by,
      show_popup: false,
      rows: [] as dynamicObj[],
      columns: [] as dynamicObj[],
      column_order: [] as string[],
      filter: '',
      loading: false,
      current_page: 1,
      page_size: 10,
      offset: 0,
      total_records: 0,
      selected_order_by: default_order_by.field_name,
      selected_order_by_direction: default_order_by.direction,
    };
  },
  computed: {
    v2Columns(): UnifiedTableColumn[] {
      return this.columns.map((col: dynamicObj) => ({
        name: col.name,
        label: this.$t(col.label),
        field: col.field || col.name,
        align: (col.align as 'left' | 'right' | 'center') || 'left',
        headerStyle: col.headerStyle,
        sortable: col.name !== 'success',
      }));
    },
    v2ColumnOrder(): string[] {
      if (this.column_order.length > 0) {
        return this.column_order;
      }
      return this.columns.map((col: dynamicObj) => col.name);
    },
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: true,
        pagination: true,
        columnReorder: true,
      };
    },
    v2PaginationState() {
      return {
        sortBy: this.selected_order_by || null,
        descending: this.selected_order_by_direction === 'desc',
        page: this.current_page,
        rowsPerPage: this.page_size,
        rowsNumber: this.total_records,
      };
    },
  },
  watch: {
    show_import_logs(new_val, old_val) {
      if (new_val && new_val !== old_val) {
        this.show_popup = true;
        this.checkConnectionLogs();
      }
    },
  },
  mounted() {
    this.init();
  },
  methods: {
    init() {
      // Nur Spalten + Pagination vorbereiten (kein Netzwerk). Die Logs werden
      // erst geladen, wenn das Popup geöffnet wird (show_import_logs-Watcher →
      // checkConnectionLogs). Diese Komponente ist im Dashboard-Header
      // (advancedSettings) fest eingebettet; ein eager Fetch hier würde
      // /email_import/import_log bei JEDEM Dashboard-Boot feuern und das
      // Dashboard hart an den import-email-Service koppeln.
      this.prepareColumns();
      this.resetPagination();
    },
    BeforePopupShow() {
      document.dispatchEvent(new CustomEvent('advancedSettingsClose'));
    },
    async checkConnectionLogs() {
      this.selected_order_by = this.default_order_by.field_name;
      this.selected_order_by_direction = this.default_order_by.direction;
      this.resetPagination();
      await this.getDataFromServer();
    },
    async getDataFromServer() {
      try {
        this.loading = true;
        const params: dynamicObj = {
          offset: this.offset,
          limit: this.page_size,
          order_by_direction: this.selected_order_by_direction,
          order_by_field: this.selected_order_by,
          filter: this.filter,
        };
        if (this.connection_id && this.connection_id > 0) {
          params.connection_id = this.connection_id;
          params.connection_type = 'email_import';
        }
        const response = await importApiService.fetchImportLogs(params);
        if (response.success === false) {
          throw { message: response.message };
        }
        this.total_records = response.element_count;
        this.prepareRows(response.data);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    prepareRows(data: any) {
      this.rows = (data || []).map((item: dynamicObj) => ({
        ...item,
        success: item.success_count > 0,
        date: this.formatDateAccordingToPreference(item.date),
        sender_display: this.parseSender(item.sender),
      }));
    },
    parseSender(sender: string): { name: string; email: string } {
      if (!sender) return { name: '', email: '' };
      const match = String(sender).match(/^\s*(.*?)\s*<([^>]+)>\s*$/);
      if (match) {
        return { name: match[1] || match[2], email: match[2] };
      }
      return { name: sender, email: '' };
    },
    resetPagination() {
      this.offset = 0;
      this.current_page = 1;
      this.total_records = 0;
      this.rows = [];
    },
    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },
    async handleV2Sort(payload: SortEventPayload) {
      if (payload.direction === null) {
        this.selected_order_by = this.default_order_by.field_name;
        this.selected_order_by_direction = this.default_order_by.direction;
      } else {
        this.selected_order_by = payload.column;
        this.selected_order_by_direction = payload.direction;
      }
      this.current_page = 1;
      this.offset = 0;
      await this.getDataFromServer();
    },
    async handleV2Pagination(payload: PaginationChangePayload) {
      this.current_page = payload.page;
      this.page_size = payload.rowsPerPage;
      this.calculateOffset();
      await this.getDataFromServer();
    },
    handleV2ColumnReorder(columnNames: string[]) {
      this.column_order = columnNames;
      LocalStorage.set(CONSTANTS.import_log_columns, JSON.stringify(columnNames));
    },
    prepareColumns() {
      this.columns = [
        {
          name: 'success',
          label: 'status',
          field: 'status',
          align: 'left',
          headerStyle: 'width: 62px',
        },
        {
          name: 'subject',
          label: 'subject',
          field: 'subject',
          align: 'left',
          headerStyle: 'width: 230px',
        },
        {
          name: 'sender',
          label: 'sender',
          field: 'sender',
          align: 'left',
          headerStyle: 'width: 230px',
        },
        {
          name: 'date',
          label: 'arrived_at',
          field: 'date',
          align: 'left',
          headerStyle: 'width: 190px',
        },
        {
          name: 'success_count',
          label: 'doc_count',
          field: 'success_count',
          align: 'left',
          headerStyle: 'width: 190px',
        },
        {
          name: 'failed_count',
          label: 'failed_count',
          field: 'failed_count',
          align: 'left',
          headerStyle: 'width: 190px',
        },
        {
          name: 'failed_filenames',
          label: 'emaillog_filename',
          field: 'failed_filenames',
          align: 'left',
        },
      ];
      const saved_columns = LocalStorage.getItem(CONSTANTS.import_log_columns) as string;
      if (saved_columns) {
        try {
          const parsed = JSON.parse(saved_columns);
          if (Array.isArray(parsed) && parsed.length > 0) {
            if (typeof parsed[0] === 'string') {
              this.column_order = parsed as string[];
            } else {
              this.column_order = parsed
                .map((c: dynamicObj) => c.name)
                .filter((n: string): n is string => !!n);
            }
          }
        } catch {
          LocalStorage.remove(CONSTANTS.import_log_columns);
        }
      }
    },
    cleanupOnhide() {
      this.show_popup = false;
      this.resetPagination();
      document.dispatchEvent(new CustomEvent('remove_advanced_settings_pop_up'));
      document.dispatchEvent(new CustomEvent('hide_import_logs'));
    },
    applyFilter() {
      this.resetPagination();
      this.getDataFromServer();
    },
  },
  setup() {
    return { getStatusIcon };
  },
});
</script>
<style scoped lang="scss">
.sender-cell {
  display: flex;
  flex-direction: column;
  line-height: 1.3;

  .sender-name {
    font-weight: 500;
  }

  .sender-email {
    font-size: 12px;
    color: var(--muted-foreground, #6b7280);
  }
}
</style>
